#!/bin/bash
# Random init dataset of set D (all 12 elements: Ti Nb Zr Hf Ta Mo W Y Re Ru V Sc; set for experiments with the
# corrections), computed from scratch (2026-11-17; no points copied from sets A/B).  START ONLY AFTER SET C HAS FINISHED.
# List slurm/compositions/TiNbZrHfTaMoWYReRuVSc_gl.csv, 2850 compositions: 1850 full simplex (seeds 10000..11849;
# same mean nearest-neighbour distance as 1000 points for 10 elements) + 100 faces for every k = 11 ... 2 (seeds
# 120000 + 1000 k + i, fractions >= 0.05).  Generated by scripts/composition_list.py (see slurm/README.md).  Full
# pipeline in GL, PBE, ew 0.6, bzqlty 10, same as the A/B databases (note: ew 0.6 is too narrow for Re-rich alloys,
# DOCS/ROZMOWA_2026-11-15_Re_ew_MoRe.md; kept for consistency with A/B).
# Default 100 tasks x <=29 interleaved rows, 6 concurrent (5 rounds of 12-component alloys, ~1-1.5 days per task):
# ~36 tasks run at once under the 512-cpu cap, the rest stay PENDING (3 waves; 100 jobs < 128 submitted per user).
#   slurm/submit_random_gl_TiNbZrHfTaMoWYReRuVSc.sh
#   env DRYRUN=1 slurm/submit_random_gl_TiNbZrHfTaMoWYReRuVSc.sh          plan only (tcsh: env VAR=x cmd)
#   env FILE=slurm/compositions/TiNbZrHfTaMoWYReRuVSc_gl.missing.csv NTASKS=20 slurm/submit_random_gl_TiNbZrHfTaMoWYReRuVSc.sh
FILE=${FILE:-slurm/compositions/TiNbZrHfTaMoWYReRuVSc_gl.csv}
WORKDIR=${WORKDIR:-random.ratios/sra.TiNbZrHfTaMoWYReRuVSc.kp10.ew0.6.gl}
NTASKS=${NTASKS:-100}; CONCURRENT=${CONCURRENT:-6}; JOBNAME=rnd12D
# run directly on the login node (it calls sbatch itself); under sbatch $0 is a spool copy without submit_complist.sh
[ -n "${SLURM_JOB_ID:-}" ] && { echo "this submit script calls sbatch itself: run it on the login node WITHOUT sbatch, e.g.  slurm/submit_random_gl_TiNbZrHfTaMoWYReRuVSc.sh"; exit 2; }
source "$(dirname "$0")/submit_complist.sh"
